// Edit these values once. Other nodes read them from here.
return [
  {
    json: {
      // Discord channel > Edit Channel > Integrations > Webhooks > Copy Webhook URL
      discordWebhookUrl: 'PASTE_YOUR_DISCORD_WEBHOOK_URL_HERE',
      // MLB team ID. 121 is the New York Mets.
      teamId: 121,
      timezone: 'America/New_York',
    },
  },
];

const { teamId, timezone } = $('Settings').first().json;
const games = ($json.dates?.[0]?.games) ?? [];

// No game today: return nothing, so no message is posted.
if (games.length === 0) return [];

const lines = games.map((game, i) => {
  const home = game.teams.home;
  const away = game.teams.away;
  const metsAreHome = home.team.id === teamId;
  const opponent = metsAreHome ? away.team.name : home.team.name;
  const vs = metsAreHome ? 'vs' : '@';
  const time = DateTime.fromISO(game.gameDate).setZone(timezone).toFormat('h:mm a ZZZZ');
  const metsPitcher = (metsAreHome ? home : away).probablePitcher?.fullName ?? 'TBD';
  const oppPitcher = (metsAreHome ? away : home).probablePitcher?.fullName ?? 'TBD';
  const label = games.length > 1 ? `**Game ${i + 1}:** ` : '';

  if (game.status.detailedState === 'Postponed') {
    return `${label}Mets ${vs} ${opponent}: **POSTPONED**`;
  }

  return [
    `${label}Mets ${vs} ${opponent}`,
    `🕖 First pitch: ${time}`,
    `🏟️ ${game.venue?.name ?? ''}`,
    `⚾ Probable pitchers: ${metsPitcher} vs ${oppPitcher}`,
  ].join('\n');
});

const header = games.length > 1 ? '🍎 **DOUBLEHEADER DAY! LET\'S GO METS!** 🍎' : '🍎 **IT\'S GAME DAY! LET\'S GO METS!** 🍎';

return [{ json: { message: [header, '', lines.join('\n\n')].join('\n') } }];
